// Independent auditor PLAY-04 service/database timing probe. Actual PostgreSQL test database and actual
// engine worker; injected simulated UTC (DB sampler) and matching monotonic time (health). Native defaults.
import assert from 'node:assert/strict';
import { randomUUID, createHash } from 'node:crypto';
import * as database from './packages/db/dist/index.js';
import { createMatchService } from './apps/match-service/dist/service.js';
import { createClockHealth } from './apps/match-service/dist/clock-health.js';
import { createEngineExecutor } from './apps/match-service/dist/engine-executor.js';
import { createReleaseRegistry } from './packages/service-runtime/dist/index.js';
import { releases, using, cleanup } from './apps/match-service/tests/fixtures.mjs';

const NATIVE = { schemaVersion: 1, id: 'qualification-dynamic-v1', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0 };
const manifest = JSON.parse(JSON.stringify(releases().active)); manifest.protocol = { min: 2, max: 3 };
manifest.releaseId = 'audit-play04-' + createHash('sha256').update(JSON.stringify(manifest)).digest('hex').slice(0, 40);
const out = {};
let utc = 1_800_000_000_000;
const owned = [];

function harness(options = {}) {
  const repository = database.createClockRepository('test', undefined, { sampleForTest: async () => utc });
  const health = createClockHealth({ monotonicNow: () => utc - 1_800_000_000_000 });
  const base = createEngineExecutor();
  let delayInspect = 0;
  const executor = { execute: async job => { if (job.kind === 'clock-inspect' && delayInspect) await new Promise(r => setTimeout(r, delayInspect)); return base.execute(job); }, project: job => base.project(job), close: () => base.close() };
  const s = createMatchService({ repository, releases: createReleaseRegistry([manifest], manifest.releaseId), executor, clocks: { repository, health, runner: { enabled: false }, recoveryAuthority: async r => (r.auditId === 'audit-recovery' ? 'audit-recovery' : null) } });
  return { s, repository, setDelay: ms => { delayInspect = ms; } };
}
const clockOf = (s, id, p = 'p1') => s.readClock(p, { matchId: id });
const rem = (c, p) => c.players.find(x => x.playerId === p).remainingMs;
async function wait(s, ms) { while (ms > 0) { const step = Math.min(ms, 10000); utc += step; ms -= step; await s.tickClocks(); } }
async function submit(s, actor, id, move, input = {}, commandId = randomUUID()) {
  const v = await s.view(actor, { matchId: id });
  return s.submit(actor, { matchId: id, commandId, expectedVersion: v.stateVersion, move, input });
}
async function stored(id) { return using('match', async c => (await c.query('SELECT state FROM match.clocks WHERE match_id=$1', [id])).rows[0].state); }
async function events(id) { return using('match', async c => (await c.query('SELECT kind,reason,audit_id FROM match.clock_events WHERE match_id=$1 ORDER BY clock_revision', [id])).rows); }

// Independent native model: charge the active player; on hand-off an exhausted outgoing player resets;
// actor receives the action bonus and, for passTurn, the turn bonus; everything is capped.
function model(active, A) { return { active, A, rem: { p1: 150000, p2: 150000 } }; }
function charge(m, t) { m.rem[m.active] -= t - m.A; }
function accept(m, t, actor, move, nextActive) {
  charge(m, t);
  if (nextActive !== m.active && m.rem[m.active] <= 0) m.rem[m.active] = 60000;
  m.rem[actor] = Math.min(150000, m.rem[actor] + 5000 + (move === 'passTurn' ? 60000 : 0));
  m.active = nextActive; m.A = t;
}
async function expectClock(s, id, m, label) {
  const c = await clockOf(s, id);
  assert.equal(c.status, 'running', label + ' status'); assert.equal(c.activePlayerId, m.active, label + ' active');
  for (const p of ['p1', 'p2']) assert.equal(rem(c, p), Math.max(0, m.rem[p] - (p === m.active ? utc - m.A : 0)), label + ' remaining ' + p);
  assert.equal(c.deadlineMs, m.A + Math.max(0, m.rem[m.active]), label + ' deadline'); assert.equal(c.serverNowMs, utc, label + ' sample');
  const st = await stored(id); assert.deepEqual(st.remainingMs, m.rem, label + ' stored remaining'); assert.equal(st.anchorUtcMs, m.A, label + ' anchor');
  return c;
}

const h = harness();
try {
  // ---------- 1. exact native arithmetic through the durable service ----------
  const id = 'audit-p04-' + randomUUID(); owned.push(id);
  await h.s.create({ matchId: id, players: ['p1', 'p2'], clock: NATIVE });
  let v = await h.s.view('p1', { matchId: id }); const chooser = v.priorityId;
  const m = model(chooser, utc); await expectClock(h.s, id, m, 'created');
  await wait(h.s, 30000); await expectClock(h.s, id, m, 'chooser thinking');
  let r = await submit(h.s, chooser, id, 'chooseWhoGoesFirst', { playerId: 'p1' }); assert.equal(r.receipt.outcome, 'accepted');
  accept(m, utc, chooser, 'chooseWhoGoesFirst', (await clockOf(h.s, id)).activePlayerId); await expectClock(h.s, id, m, 'chosen');
  for (const p of ['p1', 'p2']) { await wait(h.s, 7000); const active = (await clockOf(h.s, id)).activePlayerId; r = await submit(h.s, active, id, 'alterHand', { cardsToMulligan: [] }); assert.equal(r.receipt.outcome, 'accepted'); accept(m, utc, active, 'alterHand', (await clockOf(h.s, id)).activePlayerId); await expectClock(h.s, id, m, 'mulligan ' + p); }
  v = await h.s.view('p1', { matchId: id }); assert.equal(m.active, 'p1'); out.openingRemaining = { ...m.rem };
  // p1 inks after 12 s (accepted, +5 s), then repeats (invalid: no bonus, no anchor reset, time keeps charging)
  await wait(h.s, 12000);
  const view1 = await h.s.view('p1', { matchId: id });
  const handRef = view1.players.find(p => p.playerId === 'p1').zones.find(z => z.kind === 'hand').cards[0].ref;
  const inkIntent = { cardId: handRef };
  r = await h.s.submitRefs('p1', { matchId: id, commandId: randomUUID(), expectedVersion: view1.stateVersion, move: 'putCardIntoInkwell', input: inkIntent });
  out.inkOutcome = r.receipt.outcome + '/' + r.receipt.reason;
  if (r.receipt.outcome === 'accepted') { accept(m, utc, 'p1', 'putCardIntoInkwell', 'p1'); await expectClock(h.s, id, m, 'inked'); }
  await wait(h.s, 2000);
  const rev0 = (await clockOf(h.s, id)).clockRevision;
  const view2 = await h.s.view('p1', { matchId: id });
  const secondRef = view2.players.find(p => p.playerId === 'p1').zones.find(z => z.kind === 'hand').cards[0].ref;
  r = await h.s.submitRefs('p1', { matchId: id, commandId: randomUUID(), expectedVersion: view2.stateVersion, move: 'putCardIntoInkwell', input: { cardId: secondRef } }); out.invalidOwn = r.receipt.outcome + '/' + r.receipt.reason;
  assert.equal(r.receipt.outcome, 'rejected'); const afterInvalid = await expectClock(h.s, id, m, 'own invalid'); assert.equal(afterInvalid.clockRevision, rev0 + 2, 'processing + aborted revisions');
  // non-active participant's move: refused, active player's anchor and deadline unchanged
  r = await submit(h.s, 'p2', id, 'passTurn'); out.nonActive = r.receipt.outcome + '/' + r.receipt.reason; assert.equal(r.receipt.outcome, 'rejected');
  await expectClock(h.s, id, m, 'non-active invalid');
  // exact boundaries: act at deadline-1 (accepted), then the exact deadline refuses
  const c1 = await clockOf(h.s, id); await wait(h.s, c1.deadlineMs - 1 - utc - ((c1.deadlineMs - 1 - utc) % 10000)); utc = c1.deadlineMs - 1;
  await h.s.tickClocks().catch(() => {});
  { const vx = await h.s.view('p1', { matchId: id }); const ref = vx.players.find(p => p.playerId === 'p1').zones.find(z => z.kind === 'hand').cards[0].ref;
    r = await h.s.submitRefs('p1', { matchId: id, commandId: randomUUID(), expectedVersion: vx.stateVersion, move: 'putCardIntoInkwell', input: { cardId: ref } }); assert.equal(r.receipt.outcome, 'rejected', 'already inked at deadline-1'); }
  out.lastMs = { remainingDisplayed: rem(await clockOf(h.s, id), 'p1') }; assert.equal(out.lastMs.remainingDisplayed, 1);
  utc += 1; const lateId = randomUUID();
  r = await submit(h.s, 'p1', id, 'passTurn', {}, lateId); assert.equal(r.receipt.reason, 'clock_expired', 'exact deadline refuses');
  const dup = await submit(h.s, 'p1', id, 'passTurn', {}, lateId); assert.equal(dup.duplicate, true); assert.deepEqual(dup.receipt, r.receipt);
  // the waiting opponent's concession at the same instant is refused as clock_expired too (opponent's clock is not expired)
  r = await submit(h.s, 'p2', id, 'concede'); out.opponentConcedeAtActiveDeadline = r.receipt.outcome + '/' + r.receipt.reason;
  // timeout: system pass, native replenishment 60 s + 5 s + 60 s = 125 s; opponent gets full clock from commit time
  const versionBefore = (await h.s.view('p1', { matchId: id })).stateVersion;
  await Promise.all([h.s.tickClocks(), h.s.tickClocks()]);
  const tv = await h.s.view('p1', { matchId: id }); assert.equal(tv.stateVersion, versionBefore + 1, 'exactly one timeout transition'); assert.equal(tv.turnOwnerId, 'p2');
  accept(m, utc, 'p1', 'passTurn', 'p2'); assert.equal(m.rem.p1, 125000); await expectClock(h.s, id, m, 'after timeout');
  const sys = await using('match', c => c.query("SELECT actor_id,command_id,outcome FROM match.command_receipts WHERE match_id=$1 AND actor_id LIKE 'system-clock%'", [id]));
  assert.equal(sys.rows.length, 1); out.timeoutReceipt = sys.rows[0];
  out.afterTimeout = { ...m.rem };
  // ---------- 2. opponent spam can lock the active player's clock and bounce their genuine move ----------
  // p2 (now active) makes an ordinary accepted move; nothing reads/verifies the new checkpoint afterwards.
  await wait(h.s, 3000);
  const pv = await h.s.view('p2', { matchId: id });
  const p2Ref = pv.players.find(p => p.playerId === 'p2').zones.find(z => z.kind === 'hand').cards[0].ref;
  r = await h.s.submitRefs('p2', { matchId: id, commandId: randomUUID(), expectedVersion: pv.stateVersion, move: 'putCardIntoInkwell', input: { cardId: p2Ref } });
  assert.equal(r.receipt.outcome, 'accepted'); accept(m, utc, 'p2', 'putCardIntoInkwell', 'p2');
  const version = r.receipt.stateVersion, anchorBefore = (await stored(id)).anchorUtcMs;
  h.setDelay(400); // cold proof reconstruction for the new checkpoint (PLAY-03 measured ~0.2 s for cold work)
  const grief = h.s.submit('p1', { matchId: id, commandId: randomUUID(), expectedVersion: version, move: 'passTurn', input: {} });
  await new Promise(r2 => setTimeout(r2, 150));
  out.statusDuringOpponentCommand = (await stored(id)).status;
  try { const genuine = await h.s.submit('p2', { matchId: id, commandId: randomUUID(), expectedVersion: version, move: 'passTurn', input: {} }); out.activePlayersMoveDuringOpponentCommand = genuine.receipt.outcome; }
  catch (error) { out.activePlayersMoveDuringOpponentCommand = 'threw ' + error.code; }
  const g = await grief; out.opponentCommandOutcome = g.receipt.outcome + '/' + g.receipt.reason;
  h.setDelay(0);
  const st = await stored(id); out.afterOpponentCommand = { status: st.status, active: st.activePlayerId, anchorUnchanged: st.anchorUtcMs === anchorBefore, deadlineUnchanged: st.deadlineUtcMs === anchorBefore + st.remainingMs.p2 };
  out.events = (await events(id)).map(e => e.kind + (e.reason ? ':' + e.reason : '')).join(',');
  // ---------- 3. opening timeout pauses (no invented choice); audited resume needs an explicit reset ----------
  const id2 = 'audit-p04-' + randomUUID(); owned.push(id2);
  await h.s.create({ matchId: id2, players: ['p1', 'p2'], clock: NATIVE });
  const chooser2 = (await h.s.view('p1', { matchId: id2 })).priorityId, A2 = utc;
  await wait(h.s, 150000);
  let c2 = await clockOf(h.s, id2);
  out.openingTimeout = { status: c2.status, reason: c2.pauseReason, displayed: rem(c2, chooser2), deadline: c2.deadlineMs, stateVersion: c2.stateVersion, storedChooser: (await stored(id2)).remainingMs[chooser2] };
  assert.equal(c2.status, 'paused'); assert.equal(c2.pauseReason, 'no_legal_default'); assert.equal(c2.stateVersion, 0, 'no opening choice invented');
  assert.equal((await stored(id2)).remainingMs[chooser2], 150000 - (utc - A2));
  await assert.rejects(submit(h.s, chooser2, id2, 'chooseWhoGoesFirst', { playerId: 'p1' }), e => e.code === 'UNAVAILABLE');
  const base2 = { matchId: id2, expectedStateVersion: 0, auditId: 'audit-recovery' };
  await assert.rejects(h.s.resumeClock({ ...base2, expectedClockRevision: c2.clockRevision, operationId: 'forged', auditId: 'someone' }), e => e.code === 'FORBIDDEN');
  await assert.rejects(h.s.resumeClock({ ...base2, expectedClockRevision: c2.clockRevision - 1, operationId: 'stale-resume' }), e => e.code === 'UNAVAILABLE');
  const plainRequest = { ...base2, expectedClockRevision: c2.clockRevision, operationId: 'plain-resume' }; const plain = await h.s.resumeClock(plainRequest);
  c2 = await clockOf(h.s, id2); out.resumeWithoutReset = { status: c2.status, deadlineIsNow: c2.deadlineMs === utc, displayed: rem(c2, chooser2) };
  await h.s.tickClocks(); c2 = await clockOf(h.s, id2); out.afterImmediateRetimeout = { status: c2.status, reason: c2.pauseReason };
  const again = await h.s.resumeClock(plainRequest);
  assert.equal(again.duplicate, true, 'resume retry returns original result'); assert.equal(again.clockRevision, plain.clockRevision);
  await assert.rejects(h.s.resumeClock({ ...plainRequest, reset: { playerId: chooser2, remainingMs: 1000 } }), e => e.code === 'ID_CONFLICT');
  const reset = await h.s.resumeClock({ ...base2, expectedClockRevision: c2.clockRevision, operationId: 'reset-resume', reset: { playerId: chooser2, remainingMs: 30000 } });
  c2 = await clockOf(h.s, id2); assert.equal(c2.status, 'running'); assert.equal(rem(c2, chooser2), 30000); assert.equal(c2.deadlineMs, utc + 30000);
  await wait(h.s, 5000); r = await submit(h.s, chooser2, id2, 'chooseWhoGoesFirst', { playerId: 'p1' }); assert.equal(r.receipt.outcome, 'accepted');
  c2 = await clockOf(h.s, id2); out.afterResetChoice = rem(c2, chooser2); assert.equal(out.afterResetChoice, 30000, '30 s - 5 s + 5 s');
  void reset;
  // ---------- 4. all runners absent: a healthy second process pauses at the last trustworthy point ----------
  const id3 = 'audit-p04-' + randomUUID(); owned.push(id3);
  await h.s.create({ matchId: id3, players: ['p1', 'p2'], clock: NATIVE });
  const m3 = model((await h.s.view('p1', { matchId: id3 })).priorityId, utc);
  r = await submit(h.s, m3.active, id3, 'chooseWhoGoesFirst', { playerId: 'p1' }); accept(m3, utc, m3.active, 'chooseWhoGoesFirst', (await clockOf(h.s, id3)).activePlayerId);
  for (let i = 0; i < 2; i++) { const a = (await clockOf(h.s, id3)).activePlayerId; r = await submit(h.s, a, id3, 'alterHand', { cardsToMulligan: [] }); accept(m3, utc, a, 'alterHand', (await clockOf(h.s, id3)).activePlayerId); }
  await expectClock(h.s, id3, m3, 'outage match opened');
  await wait(h.s, 20000); const healthyUntil = (await stored(id3)).lastHealthyUtcMs; assert.equal(healthyUntil, utc);
  utc += 40000; // no runner anywhere for 40 s
  await assert.rejects(submit(h.s, 'p1', id3, 'passTurn'), e => e.code === 'UNAVAILABLE');
  out.quarantinedLocalOwner = { dbStatusWhileOnlyOwnerQuarantined: (await stored(id3)).status };
  const h2 = harness();
  try {
    await h2.s.tickClocks();
    let c3 = await clockOf(h2.s, id3);
    out.outagePause = { status: c3.status, reason: c3.pauseReason, displayedActive: rem(c3, m3.active), expected: m3.rem[m3.active] - (healthyUntil - m3.A) };
    assert.equal(c3.status, 'paused'); assert.equal(rem(c3, m3.active), m3.rem[m3.active] - (healthyUntil - m3.A));
    const resumed = await h2.s.resumeClock({ matchId: id3, expectedStateVersion: c3.stateVersion, expectedClockRevision: c3.clockRevision, operationId: 'outage-resume', auditId: 'audit-recovery' });
    void resumed; c3 = await clockOf(h2.s, id3);
    m3.rem[m3.active] -= healthyUntil - m3.A; m3.A = utc; await expectClock(h2.s, id3, m3, 'resumed after outage (outage not charged)');
    await wait(h2.s, 1000); r = await submit(h2.s, 'p1', id3, 'passTurn'); assert.equal(r.receipt.outcome, 'accepted'); accept(m3, utc, 'p1', 'passTurn', 'p2'); await expectClock(h2.s, id3, m3, 'move after audited resume');
    out.outageCharged = 150000 - m3.rem.p1;
  } finally { await h2.s.close(); }
} catch (error) { out.error = String(error && error.message); } finally {
  await h.s.close();
  for (const id of owned) await cleanup(id).catch(() => {});
}
console.log(JSON.stringify(out));
